#import "TrafficLightOverlayView.h"
@implementation TrafficLightOverlayView
- (instancetype)initWithFrame:(CGRect)f { if((self=[super initWithFrame:f])){ self.userInteractionEnabled=NO; self.backgroundColor=UIColor.clearColor; self.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight; } return self; }
- (void)showDetections:(NSArray<TATrafficLightDetection *> *)items { [self.layer.sublayers makeObjectsPerformSelector:@selector(removeFromSuperlayer)]; for(TATrafficLightDetection *d in items){ CGRect n=d.normalizedRect; CGRect r=CGRectMake(n.origin.x*self.bounds.size.width,(1.0-n.origin.y-n.size.height)*self.bounds.size.height,n.size.width*self.bounds.size.width,n.size.height*self.bounds.size.height); CAShapeLayer *b=[CAShapeLayer layer]; b.frame=r; b.path=[UIBezierPath bezierPathWithRoundedRect:b.bounds cornerRadius:4].CGPath; b.fillColor=UIColor.clearColor.CGColor; UIColor *c=UIColor.cyanColor; if([d.label containsString:@"red"])c=UIColor.redColor; else if([d.label containsString:@"yellow"])c=UIColor.yellowColor; else if([d.label containsString:@"green"])c=UIColor.greenColor; b.strokeColor=c.CGColor; b.lineWidth=3; [self.layer addSublayer:b]; } }
@end
